    public IResult Content(Dictionary<string, object?> i, bool preview) { if ((string)i["kind"] != "file") throw new ArgumentException("Not a file"); var path = disk.Blob((string)i["blob"]!); if (!File.Exists(path)) throw new IOException("File storage is unavailable"); var ext = Path.GetExtension((string)i["name"]!).ToLowerInvariant(); var mime = ext switch { ".jpg" or ".jpeg" => "image/jpeg", ".png" => "image/png", ".webp" => "image/webp", ".gif" => "image/gif", ".txt" or ".md" or ".csv" or ".log" => "text/plain", ".pdf" => "application/pdf", ".mp4" => "video/mp4", ".webm" => "video/webm", ".mp3" => "audio/mpeg", ".wav" => "audio/wav", ".ogg" => "audio/ogg", _ => "application/octet-stream" }; return Results.File(path, preview ? mime : "application/octet-stream", preview && mime != "application/octet-stream" ? null : (string)i["name"]!, enableRangeProcessing: true); }
    void SaveVersion(SqliteConnection c, Dictionary<string, object?> i) => Database.Exec(c, "INSERT INTO versions VALUES($id,$i,$b,$s,$h,$n,$r)", ("$id", Id()), ("$i", i["id"]), ("$b", i["blob"]), ("$s", i["size"]), ("$h", i["checksum"]), ("$n", Database.Now), ("$r", i["revision"]));
